#### For full credit, please implement the function in Python:

    def f(h: int, w: int, n: int, grid: List[str]) -> int:
        '''
        h: an integer
        w: an integer
        n: an integer
        grid: a list of strings
        '''
        for c in range(w):
            for r in range(h - 1, -1, -1):
                if grid[r][c] == '.':
                    continue
                nr = r - 1
                while nr >= 0 and grid[nr][c] == '.':
                    nr -= 1
                if r - nr - 1 >= n:
                    return r + 1
        return -1


An integer h (2 ≤ h ≤ 30), representing the height of the grid. 
An integer w (2 ≤ w ≤ 30), representing the width of the grid. 
The grid contains characters ('A' - 'Z') and periods ('.'). 
A lowercase letter in the grid represents a character from the grid, and its uppercase equivalent represents a copy of that character.

#### Return 
    This function returns an integer representing the number of occurrences of the input string in the grid. 
    For full credit, your submission should have a time complexity of O(h*w*n). 

def f(h: int, w: int, n: int, grid: List[str]) -> int:
        def left_up(r, c):
            while r >= 0 and c >= 0 and grid[r][c] == '.':
                r -= 1
                c -= 1
            return r, c

        def left_down(r, c):
            while r < h and c >= 0 and grid[r][c] == '.':
                r += 1
                c -= 1
            return r, c

        def right_up(r, c):
            while r >= 0 and c < w and grid[r][c] == '.':
                r -= 1
                c += 1
            return r, c

        def right_down(r, c):
            while r < h and c < w and grid[r][c] == '.':
                r += 1
                c += 1
            return r, c

        def check(r, c, n):
            r1, c1 = left_up(r, c)
            r2, c2 = left_down(r, c)
            r3, c3 = right_up(r, c)
            r4, c4 = right_down(r, c)
            dist_left = min(abs(r - r1), abs(c - c1)) + 1
            dist_right = min(abs(r - r2), abs(c - c2)) + 1
            dist_up = min(abs(r - r3), abs(c - c3)) + 1
            dist_down = min(abs(r - r4), abs(c - c4)) + 1
            return max(dist_left, dist_right, dist_up, dist_down) >= n

        res = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] == '.':
                    continue
                if check(r, c, n):
                    res += 1
        return res

